  1→import React, { useState, useCallback, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import AppHeader from "@/components/AppHeader";
  5→import AuthDialog from "@/components/AuthDialog";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import JobDetailView from "@/components/JobDetailView";
  8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  9→import { toast } from "sonner";
 10→
 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→  inbox_email: string | null;
 21→}
 22→
 23→export interface Result {
 24→  id: string;
 25→  resume_id: string;
 26→  overall_score: number;
 27→  missing_skills: string[];
 28→  summary: string | null;
 29→  interview_questions: any;
 30→  filename: string;
 31→  file_path: string | null;
 32→  candidate_name: string | null;
 33→  candidate_email?: string | null;
 34→  candidate_phone?: string | null;
 35→  candidate_location?: string | null;
 36→  // Dynamic scoring fields
 37→  hard_fit?: boolean;
 38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 39→  confidence?: number;
 40→  strengths_json?: string[];
 41→  gaps_json?: string[];
 42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string };
 43→  matched_must_haves?: string[];
 44→  missing_must_haves?: string[];
 45→  scoring_version?: string;
 46→  pending?: boolean;
 47→  parsed_json?: any;
 48→}
 49→
 50→export interface ExistingResume {
 51→  id: string;
 52→  filename: string;
 53→  file_path: string | null;
 54→  candidate_name: string | null;
 55→  created_at: string;
 56→}
 57→
 58→const Index = () => {
 59→  const { user } = useAuth();
 60→
 61→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 62→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 63→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 64→  const [results, setResults] = useState<Result[]>([]);
 65→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 66→  const [authOpen, setAuthOpen] = useState(false);
 67→
 68→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 69→
 70→  const fetchPastJobs = useCallback(async () => {
 71→    if (!user) return;
 72→    setLoadingPastJobs(true);
 73→    try {
 74→      const { data: jobs } = await supabase
 75→        .from("jobs")
 76→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 77→        .eq("user_id", user.id)
 78→        .order("created_at", { ascending: false })
 79→        .limit(50);
 80→      if (jobs) {
 81→        setPastJobs(jobs.map((j: any) => ({
 82→          id: j.id,
 83→          title: j.title,
 84→          job_description: j.job_description,
 85→          status: j.status,
 86→          created_at: j.created_at,
 87→          resume_count: j.resumes?.[0]?.count ?? 0,
 88→          jd_analysis_json: j.jd_analysis_json,
 89→          dynamic_weights_json: j.dynamic_weights_json,
 90→          inbox_email: j.inbox_email ?? null,
 91→        })));
 92→      }
 93→    } catch (err) {
 94→      console.error("Failed to load past jobs:", err);
 95→    } finally {
 96→      setLoadingPastJobs(false);
 97→    }
 98→  }, [user]);
 99→
100→  useEffect(() => {
101→    fetchPastJobs();
102→  }, [fetchPastJobs]);
103→
104→  const loadJobData = async (jobId: string) => {
105→    setSelectedJobId(jobId);
106→    try {
107→      const [resumesRes, resumeListRes] = await Promise.all([
108→        supabase
109→          .from("resumes")
110→          .select("id, filename, file_path, candidate_name, created_at")
111→          .eq("job_id", jobId)
112→          .order("created_at", { ascending: false }),
113→        supabase
114→          .from("resumes")
115→          .select("id, filename, file_path, candidate_name, parsed_json")
116→          .eq("job_id", jobId),
117→      ]);
118→
119→      const resumes = resumesRes.data ?? [];
120→      setExistingResumes(resumes);
121→
122→      const resumeData = (resumeListRes.data ?? []) as Array<{
123→        id: string;
124→        filename: string;
125→        file_path: string | null;
126→        candidate_name: string | null;
127→        parsed_json?: any;
128→      }>;
129→      if (resumeData.length === 0) {
130→        setResults([]);
131→        return;
132→      }
133→
134→      const resumeIds = resumeData.map((r) => r.id);
135→      const { data: resultData } = await supabase
136→        .from("results")
137→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
138→        .in("resume_id", resumeIds);
139→
140→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
141→      const merged: Result[] = (resultData ?? []).map((r: any) => {
142→        const resume = resumeMap.get(r.resume_id);
143→        const parsed = resume?.parsed_json as any;
144→        return {
145→          ...r,
146→          overall_score: r.overall_score ?? 0,
147→          missing_skills: r.missing_skills ?? [],
148→          filename: resume?.filename ?? "Unknown",
149→          file_path: resume?.file_path ?? null,
150→          candidate_name: resume?.candidate_name ?? null,
151→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
152→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
153→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
154→          parsed_json: resume?.parsed_json ?? null,
155→        };
156→      });
157→      merged.sort((a, b) => b.overall_score - a.overall_score);
158→      setResults(merged);
159→    } catch (err) {
160→      console.error("Failed to load job data:", err);
161→      toast.error("Failed to load job data");
162→    }
163→  };
164→
165→  const handleNewJob = () => {
166→    setSelectedJobId(null);
167→    setResults([]);
168→    setExistingResumes([]);
169→  };
170→
171→  const handleJobCreated = (job: PastJob) => {
172→    setPastJobs((prev) => [job, ...prev]);
173→    setSelectedJobId(job.id);
174→    loadJobData(job.id);
175→  };
176→
177→  const handleRenameJob = (jobId: string, newTitle: string) => {
178→    setPastJobs((prev) =>
179→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
180→    );
181→  };
182→
183→  const handleDeleteJob = async (jobId: string) => {
184→    try {
185→      await supabase.from("resumes").delete().eq("job_id", jobId);
186→      await supabase.from("jobs").delete().eq("id", jobId);
187→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
188→      if (selectedJobId === jobId) handleNewJob();
189→      toast.success("Job deleted");
190→    } catch {
191→      toast.error("Failed to delete job");
192→    }
193→  };
194→
195→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
196→    setPastJobs((prev) =>
197→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
198→    );
199→  };
200→
201→  const requireAuth = useCallback(() => {
202→    if (!user) { setAuthOpen(true); return true; }
203→    return false;
204→  }, [user]);
205→
206→  return (
207→    <SidebarProvider className="h-svh overflow-hidden">
208→      <JobSidebar
209→        pastJobs={pastJobs}
210→        selectedJobId={selectedJobId}
211→        loadingPastJobs={loadingPastJobs}
212→        onSelectJob={loadJobData}
213→        onNewJob={handleNewJob}
214→        onRenameJob={handleRenameJob}
215→        onDeleteJob={handleDeleteJob}
216→        onAuthRequired={() => setAuthOpen(true)}
217→        isAuthenticated={!!user}
218→      />
219→
220→      <SidebarInset className="h-svh overflow-y-auto">
221→        <AppHeader />
222→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
223→          <SidebarTrigger />
224→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
225→        </div>
226→        <JobDetailView
227→          selectedJobId={selectedJobId}
228→          selectedJob={selectedJob}
229→          results={results}
230→          setResults={setResults}
231→          existingResumes={existingResumes}
232→          setExistingResumes={setExistingResumes}
233→          onJobCreated={handleJobCreated}
234→          onAuthRequired={() => setAuthOpen(true)}
235→          isAuthenticated={!!user}
236→          onJobUpdated={handleJobUpdated}
237→        />
238→      </SidebarInset>
239→
240→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
241→    </SidebarProvider>
242→  );
243→};
244→
245→export default Index;
246→

  1→import { useState, useCallback, useRef, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { usePlatformConfig } from "@/hooks/usePlatformConfig";
  4→import { supabase } from "@/integrations/supabase/client";
  5→import { Button } from "@/components/ui/button";
  6→import { Textarea } from "@/components/ui/textarea";
  7→import { Checkbox } from "@/components/ui/checkbox";
  8→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  9→import { Badge } from "@/components/ui/badge";
 10→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
 11→import { Progress } from "@/components/ui/progress";
 12→import {
 13→  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
 14→  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
 15→} from "@/components/ui/alert-dialog";
 16→import { toast } from "sonner";
 17→import {
 18→  Upload, Copy, Loader2, FileText,
 19→  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2, FileSpreadsheet,
 20→  Brain, ListChecks, BarChart2, ArrowRight, Sparkles, Clock, Users, Star, Mail, Zap,
 21→  Archive, ArchiveRestore, FolderOpen, Wand2
 22→} from "lucide-react";
 23→import { exportToCSV } from "@/lib/csvExport";
 24→import CandidateRow from "@/components/CandidateRow";
 25→import JDRewriteDialog from "@/components/JDRewriteDialog";
 26→import ScoreSummaryCards from "@/components/ScoreSummaryCards";
 27→import ConfidenceReport from "@/components/ConfidenceReport";
 28→import type { PastJob, Result, ExistingResume } from "@/pages/Index";
 29→import { useStages, useUpdateStage, useStageSummary, STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
 30→
 31→interface JobDetailViewProps {
 32→  selectedJobId: string | null;
 33→  selectedJob: PastJob | null;
 34→  results: Result[];
 35→  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
 36→  existingResumes: ExistingResume[];
 37→  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
 38→  onJobCreated: (job: PastJob) => void;
 39→  onAuthRequired: () => void;
 40→  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
 41→  isAuthenticated?: boolean;
 42→}
 43→
 44→interface UploadedFile {
 45→  file: File;
 46→  name: string;
 47→}
 48→
 49→const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 50→
 51→const JobDetailView = ({
 52→  selectedJobId,
 53→  selectedJob,
 54→  results,
 55→  setResults,
 56→  existingResumes,
 57→  setExistingResumes,
 58→  onJobCreated,
 59→  onAuthRequired,
 60→  onJobUpdated,
 61→  isAuthenticated = true,
 62→}: JobDetailViewProps) => {
 63→  const { user, profile, refreshProfile } = useAuth();
 64→  const { data: config } = usePlatformConfig();
 65→
 66→  const [jobDescription, setJobDescription] = useState("");
 67→  const [files, setFiles] = useState<UploadedFile[]>([]);
 68→  const [ranking, setRanking] = useState(false);
 69→  const [rankingProgress, setRankingProgress] = useState(0);
 70→  const [scoredCount, setScoredCount] = useState(0);
 71→  const [totalToScore, setTotalToScore] = useState(0);
 72→  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
 73→  const [dragOver, setDragOver] = useState(false);
 74→  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
 75→  const [validationErrors, setValidationErrors] = useState<string[]>([]);
 76→  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
 77→  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
 78→  const [deleting, setDeleting] = useState(false);
 79→  const [analyzingJd, setAnalyzingJd] = useState(false);
 80→  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
 81→  const [showArchived, setShowArchived] = useState(false);
 82→  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
 83→
 84→  const resultsRef = useRef<HTMLDivElement>(null);
 85→  const rankingFilesRef = useRef<Set<string>>(new Set());
 86→  const maxResumes = config?.max_resumes_per_job ?? 10;
 87→  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
 88→
 89→  const isNewJobMode = selectedJobId === null;
 90→  const isExistingJob = selectedJobId !== null && selectedJob !== null;
 91→
 92→  // Hiring Stage Tracker
 93→  const { data: stages } = useStages(selectedJobId);
 94→  const updateStageMutation = useUpdateStage();
 95→  const stageSummary = useStageSummary(selectedJobId);
 96→  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));
 97→
 98→  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
 99→    if (!selectedJobId) return;
100→    const current = stageMap.get(resumeId);
101→    updateStageMutation.mutate({
102→      resumeId,
103→      jobId: selectedJobId,
104→      newStage,
105→      currentStage: current?.stage,
106→    });
107→  };
108→
109→  const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
110→  const formatCandidateName = (filename: string) => {
111→    const name = filename.replace(/\.\w+$/, "");
112→    if (UUID_REGEX.test(name)) return `Candidate`;
113→    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
114→  };
115→
116→  // Merge unranked resumes
117→  const resultResumeIds = new Set(results.map((r) => r.resume_id));
118→  const pendingResumes: Result[] = existingResumes
119→    .filter((r) => !resultResumeIds.has(r.id))
120→    .map((r) => ({
121→      id: `pending-${r.id}`,
122→      resume_id: r.id,
123→      overall_score: 0,
124→      missing_skills: [], summary: null, interview_questions: null,
125→      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
126→      pending: true,
127→    }));
128→  const allResults = [...results, ...pendingResumes];
129→
130→  // Selection helpers
131→  const toggleSelectResume = (resumeId: string) => {
132→    setSelectedResumes((prev) => {
133→      const next = new Set(prev);
134→      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
135→      return next;
136→    });
137→  };
138→  const toggleSelectAll = () => {
139→    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
140→    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
141→  };
142→
143→  // Delete logic
144→  const deleteResume = async (resumeId: string, filePath: string | null) => {
145→    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
146→    await supabase.from("results").delete().eq("resume_id", resumeId);
147→    await supabase.from("resumes").delete().eq("id", resumeId);
148→    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
149→    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
150→    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
151→  };
152→
153→  const handleDeleteConfirm = async () => {
154→    if (!deleteConfirm) return;
155→    setDeleting(true);
156→    try {
157→      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
158→        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
159→        toast.success("Resume deleted");
160→      } else if (deleteConfirm.type === "bulk") {
161→        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
162→        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
163→        toast.success(`${toDelete.length} resume(s) deleted`);
164→      }
165→    } catch { toast.error("Failed to delete"); }
166→    finally { setDeleting(false); setDeleteConfirm(null); }
167→  };
168→
169→  // File handling
170→  const handleFileDrop = useCallback((e: React.DragEvent) => {
171→    e.preventDefault(); setDragOver(false);
172→    const dropped = Array.from(e.dataTransfer.files).filter(
173→      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
174→    );
175→    addFiles(dropped);
176→  }, [files, maxResumes, maxFileSizeMb]);
177→
178→  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
179→    if (e.target.files) addFiles(Array.from(e.target.files));
180→  };
181→
182→  const addFiles = (newFiles: File[]) => {
183→    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
184→    const valid = newFiles.filter((f) => {
185→      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
186→      return true;
187→    });
188→    const remaining = maxResumes - currentCount;
189→    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
190→    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
191→    setFiles((prev) => [...prev, ...toAdd]);
192→  };
193→
194→  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
195→  const toggleRow = (id: string) => {
196→    setExpandedRows((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
197→  };
198→
199→  const copyInboxEmail = () => {
200→    if (profile?.inbox_email) { navigator.clipboard.writeText(profile.inbox_email); toast.success("Inbox email copied!"); }
201→  };
202→
203→  const validate = (): string[] => {
204→    const errors: string[] = [];
205→    if (isNewJobMode && !jobDescription.trim()) errors.push("Job description is required.");
206→    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
207→    if (filesToCheck.length === 0) errors.push("Upload at least one resume.");
208→    const splitTotal = (profile?.subscription_credits ?? 0) + (profile?.topup_credits ?? 0);
209→    const totalCredits = splitTotal > 0 ? splitTotal : (profile?.credits ?? 0);
210→    if (user && totalCredits < Math.min(filesToCheck.length, 20)) {
211→      errors.push(`Not enough credits. You need ${Math.min(filesToCheck.length, 20)} but have ${totalCredits}.`);
212→    }
213→    return errors;
214→  };
215→
216→  // ── Analyze JD ──────────────────────────────────────────────
217→  const analyzeJd = async (jobId: string) => {
218→    setAnalyzingJd(true);
219→    try {
220→      const response = await fetch(
221→        `https://zkzontawprihrzpayeam.supabase.co/functions/v1/analyze-jd`,
222→        {
223→          method: "POST",
224→          headers: {
225→            "Content-Type": "application/json",
226→            Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
227→          },
228→          body: JSON.stringify({ job_id: jobId }),
229→        }
230→      );
231→      if (!response.ok) {
232→        const err = await response.json().catch(() => ({}));
233→        throw new Error(err.error || "JD analysis failed");
234→      }
235→      const data = await response.json();
236→      if (onJobUpdated) {
237→        onJobUpdated(jobId, {
238→          jd_analysis_json: data.jd_analysis,
239→          dynamic_weights_json: data.dynamic_weights,
240→        });
241→      }
242→      return data;
243→    } catch (err: any) {
244→      toast.error(err.message || "JD analysis failed");
245→      throw err;
246→    } finally {
247→      setAnalyzingJd(false);
248→    }
249→  };
250→
251→  // ── Load dismissed resumes from localStorage when job changes ──
252→  useEffect(() => {
253→    setShowArchived(false);
254→    if (selectedJobId) {
255→      try {
256→        const stored = localStorage.getItem(`dismissed_${selectedJobId}`);
257→        if (stored) {
258→          setDismissedResumes(new Set(JSON.parse(stored) as string[]));
259→        } else {
260→          setDismissedResumes(new Set());
261→        }
262→      } catch {
263→        setDismissedResumes(new Set());
264→      }
265→    } else {
266→      setDismissedResumes(new Set());
267→    }
268→  }, [selectedJobId]);
269→
270→  // ── Auto-rank ───────────────────────────────────────────────
271→  const autoRankTriggered = useRef(false);
272→  useEffect(() => {
273→    const unrankedFiles = files.filter(f => !rankingFilesRef.current.has(f.name));
274→    if (unrankedFiles.length > 0 && !ranking && !autoRankTriggered.current) {
275→      if (isNewJobMode && !jobDescription.trim()) return;
276→      autoRankTriggered.current = true;
277→      handleRankClick();
278→    }
279→    if (files.length === 0 && !ranking) autoRankTriggered.current = false;
280→  }, [files, ranking, isNewJobMode, jobDescription]);
281→
282→  const handleRankingError = (err: any) => {
283→    const msg: string = err?.message || "Ranking failed.";
284→    if (msg.includes("Insufficient credits") || err?.status === 402) {
285→      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
286→    } else if (msg.includes("Rate limit") || err?.status === 429) {
287→      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
288→    } else {
289→      setRankingError({ type: "generic", message: msg });
290→      toast.error(msg);
291→    }
292→  };
