 17→/** Send an email via Postmark API */
 18→async function sendViaPostmark(
 19→  apiToken: string,
 20→  from: { email: string; name: string },
 21→  to: string,
 22→  subject: string,
 23→  htmlContent: string
 24→): Promise<{ ok: boolean; status: number; body: string; errorCode?: number; errorMessage?: string }> {
 25→  const res = await fetch("https://api.postmarkapp.com/email", {
 26→    method: "POST",
 27→    headers: {
 28→      "Accept": "application/json",
 29→      "Content-Type": "application/json",
 30→      "X-Postmark-Server-Token": apiToken,
 31→    },
 32→    body: JSON.stringify({
 33→      From: `${from.name} <${from.email}>`,
 34→      To: to,
 35→      Subject: subject,
 36→      HtmlBody: htmlContent,
 37→      MessageStream: "outbound",
 38→    }),
 39→  });
 40→
 41→  const body = await res.text();
 42→  let errorCode: number | undefined;
 43→  let errorMessage: string | undefined;
 44→
 45→  if (!res.ok) {
 46→    try {
 47→      const parsed = JSON.parse(body);
 48→      errorCode = parsed.ErrorCode;
 49→      errorMessage = parsed.Message;
 50→    } catch { /* ignore */ }
 51→  }
 52→
 53→  return { ok: res.ok, status: res.status, body, errorCode, errorMessage };
 54→}
