 56→serve(async (req) => {
 57→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 58→
 59→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 60→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 61→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 62→
 63→  // Verify JWT
 64→  const authHeader = req.headers.get("Authorization");
 65→  if (!authHeader) {
 66→    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
 67→      status: 401,
 68→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 69→    });
 70→  }
 71→
 72→  const token = authHeader.replace("Bearer ", "");
 73→  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
 74→  if (authError || !user) {
 75→    return new Response(JSON.stringify({ error: "Unauthorized" }), {
 76→      status: 401,
 77→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 78→    });
 79→  }
 80→
 81→  try {
 82→    const { resume_id, job_id, to_email, subject, body_html } =
 83→      (await req.json()) as SendCandidateEmailRequest;
 84→
 85→    if (!resume_id || !job_id || !to_email || !subject || !body_html) {
 86→      return new Response(
 87→        JSON.stringify({ error: "Missing required fields: resume_id, job_id, to_email, subject, body_html" }),
 88→        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
 89→      );
 90→    }
 91→
 92→    // Load platform config for Postmark credentials
 93→    const { data: config, error: configError } = await supabase
 94→      .from("platform_config")
 95→      .select("postmark_api_token, email_from_address, email_from_name, outbound_email_enabled")
 96→      .limit(1)
 97→      .single();
 98→
 99→    if (configError) throw new Error(`Config error: ${configError.message}`);
100→
101→    if (!config?.outbound_email_enabled) {
102→      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
103→        status: 200,
104→        headers: { ...corsHeaders, "Content-Type": "application/json" },
105→      });
106→    }
107→
108→    if (!config.postmark_api_token) {
109→      return new Response(JSON.stringify({ error: "Postmark API token not configured" }), {
110→        status: 400,
111→        headers: { ...corsHeaders, "Content-Type": "application/json" },
112→      });
113→    }
114→
115→    const fromEmail = config.email_from_address || "noreply@rankora.co";
116→    const fromName = config.email_from_name || "Rankora";
117→
118→    // Send via Postmark
119→    const result = await sendViaPostmark(
120→      config.postmark_api_token,
121→      { email: fromEmail, name: fromName },
122→      to_email,
123→      subject,
124→      body_html
125→    );
126→
127→    const logStatus = result.ok ? "sent" : "failed";
128→
129→    // Log to outreach_log regardless of send result
130→    const { error: logError } = await supabase.from("outreach_log").insert({
131→      resume_id,
132→      job_id,
133→      type: "email",
134→      to_address: to_email,
135→      subject,
136→      status: logStatus,
137→      user_id: user.id,
138→    });
139→
140→    if (logError) {
141→      console.error("Failed to log outreach:", logError.message);
142→    }
143→
144→    if (!result.ok) {
145→      let errorMessage = result.errorMessage || `Postmark error (status ${result.status})`;
146→      if (result.errorCode === 412) {
147→        errorMessage = `Account pending approval — emails can only be sent to verified addresses while your Postmark account is being reviewed.`;
148→      } else if (result.errorCode === 406) {
149→        errorMessage = `Inactive recipient — ${to_email} has been marked as inactive due to previous bounces.`;
150→      } else if (result.errorCode === 300) {
151→        errorMessage = `Sender signature not found — ${fromEmail} is not verified in Postmark.`;
152→      } else if (result.errorCode === 401) {
153→        errorMessage = `Unauthorized — your Postmark API token is invalid or expired.`;
154→      }
155→
156→      console.error("Postmark error:", result.status, result.body);
157→      return new Response(
158→        JSON.stringify({
159→          error: errorMessage,
160→          postmark_error_code: result.errorCode,
161→        }),
162→        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
163→      );
164→    }
165→
166→    return new Response(JSON.stringify({ success: true }), {
167→      status: 200,
168→      headers: { ...corsHeaders, "Content-Type": "application/json" },
169→    });
170→  } catch (err: unknown) {
171→    console.error("send-candidate-email error:", err);
172→    return new Response(
173→      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
174→      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
175→    );
176→  }
